        '“죽은 뿌리 껍질을 파먹는 갑충 군락은 개체의 죽음을 세지 않고 오직 살아남은 외피만 대물림한다.”': '“啃食枯死根皮的甲虫群落不计个体的死亡，只把存活下来的外壳代代相传。”',
        '“열 번의 범람을 막아낸 방벽 위에는 벌레의 체액 대신 꺾이지 않는 살의가 굳어 붙었다.”': '“在挡下十次泛滥的壁垒上，凝固的不是虫子的体液，而是不屈的杀意。”',
        '히든 저널, 초월의 가지': '隐藏日志，超越之枝',
        '경험치 획득 +2%': '经验获取 +2%',
        '레벨 200에 닿은 날의 기록입니다.': '抵达 200 级那天的记录。',
        '레벨 200 달성': '达到 200 级',
        '“필멸의 한계를 넘어 두 번째 백(百)의 고리에 도달한 기록.”': '“跨越必死之限，抵达第二个百之环的记录。”',
        '“비대해진 영혼의 무게를 이기지 못해 주변의 나이테가 스스로 길을 비킨다.”': '“周围的年轮承受不住膨胀灵魂的重量，自行让开了路。”',
