        '직업 방향의 공허 소켓 여섯을 모두 활성화': '激活职业方向的全部六个虚空插槽',
        '“여섯 외곽 성률의 파편들이 하나의 완전한 천구(天球) 문양으로 맞물렸다.”': '“六个外围星律的碎片，咬合成了一个完整的天球纹章。”',
