        '“부러지기 직전의 강철이 가장 서늘한 궤적을 그린다.”': '“濒临断裂的钢铁，划出最凛冽的轨迹。”',
        '“꺼져가던 박동 끝에서 마침내 거대한 적의 숨통을 먼저 끊어낸 기록.”': '“在渐息的心跳尽头，终于先一步断绝了巨大敌人气息的记录。”',
        '히든 저널, 상처 없는 승리': '隐藏日志，无伤的胜利',
        '최종 관문 보스를 생명력 피해 없이 쓰러뜨린 기록입니다.': '在未受生命伤害的情况下击败最终关卡首领的记录。',
        '최종 관문 보스를 생명력 피해 없이 처치': '未受生命伤害击杀最终关卡首领',
        '“단 한 방울의 피도 흘리지 않고 정점의 포식자를 베어 넘겼다.”': '“未流一滴血，便斩倒了顶点的掠食者。”',
        '“상처조차 남기지 않은 완벽한 절단면의 기록.”': '“连伤痕都未留下的完美切面的记录。”',
        '히든 저널, 네 겹의 흉터': '隐藏日志，四重伤痕',
