        '한 보스에게 서로 다른 상태 이상 4종을 부여한 뒤 처치': '对同一首领施加 4 种不同异常状态后击杀',
        '“화염과 서리, 맹독과 뇌전이 한 육신 위에서 얽혀 들어갔다.”': '“火焰与寒霜、剧毒与雷电，在同一具躯体上交织而入。”',
        '“네 가지 재앙으로 속살까지 파고든 끝에야 비로소 무너진 거목의 기록.”': '“四种灾厄深入骨肉之后方才倒塌的巨木的记录。”',
        '버려진 날, 과열(제2호 폐기록)': '被遗弃的刃，过热（第 2 号废弃录）',
