        '“제2호 시제품: 극한의 속도를 얻었으나 제 열기를 이기지 못해 손잡이까지 녹아내림. 우물 외곽에 폐기한다.”': '“第 2 号试制品：获得了极限速度，却承受不住自身热量，连刀柄都熔化了。废弃于井的外缘。”',
        '(벼림꾼 오르가의 모루터 폐기 장부 제2항)': '（锻造师奥尔加的铁砧废弃账簿第 2 项）',
        '버려진 날, 무딤(제3호 폐기록)': '被遗弃的刃，钝化（第 3 号废弃录）',
        '모루터에서 버려진 세 번째 날, 무딤을 꺾은 기록입니다.': '击败在铁砧之地被遗弃的第三把刃“钝化”的记录。',
        '“제3호 시제품: 결코 부러지지 않는 두께를 지녔으나, 아무것도 베지 못하는 쇳덩이에 불과함. 폐기한다.”': '“第 3 号试制品：拥有绝不断裂的厚度，却不过是什么也砍不动的铁块。废弃。”',
        '(벼림꾼 오르가의 모루터 폐기 장부 제3항)': '（锻造师奥尔加的铁砧废弃账簿第 3 项）',
