        '모루터에서 버려진 네 번째 날, 탐식을 꺾은 기록입니다.': '击败在铁砧之地被遗弃的第四把刃“暴食”的记录。',
        '“제4호 시제품: 베어낸 적의 피와 수액을 삼켜 스스로 상처를 메우나, 배가 부르면 날이 무뎌짐. 폐기한다.”': '“第 4 号试制品：吞噬所斩敌人的血与树液以自愈，但吃饱后刃口变钝。废弃。”',
        '(벼림꾼 오르가의 모루터 폐기 장부 제4항)': '（锻造师奥尔加的铁砧废弃账簿第 4 项）',
