        '“제5호 시제품: 허공을 가르는 그림자처럼 부딪힘을 피하나, 나무껍질의 저항 앞에서는 미끄러질 뿐임. 폐기한다.”': '“第 5 号试制品：如划破虚空的影子般躲避碰撞，但在树皮的阻力面前只会打滑。废弃。”',
        '(벼림꾼 오르가의 모루터 폐기 장부 제5항)': '（锻造师奥尔加的铁砧废弃账簿第 5 项）',
        '버려진 날, 역린(제6호 폐기록)': '被遗弃的刃，逆鳞（第 6 号废弃录）',
        '모루터에서 버려진 여섯 번째 날, 역린을 꺾은 기록입니다.': '击败在铁砧之地被遗弃的第六把刃“逆鳞”的记录。',
        '“제6호 시제품: 갑주의 안쪽을 파고드는 역날 구조이나, 쥐는 이의 손목까지 함께 벤다. 폐기한다.”': '“第 6 号试制品：能切入甲胄内侧的逆刃结构，但会连持握者的手腕一起割伤。废弃。”',
        '(벼림꾼 오르가의 모루터 폐기 장부 제6항)': '（锻造师奥尔加的铁砧废弃账簿第 6 项）',
        '일곱 번째 날, 완성작(제7호 봉인록)': '第七把刃，完成之作（第 7 号封印录）',
        '나무꾼이 끝내 손에서 놓지 않은 일곱 번째 날, 완성작을 꺾은 기록입니다.': '击败樵夫始终不肯放手的第七把刃“完成之作”的记录。',
        '“제7호 최종본: 앞선 다섯 시제품의 결함을 모두 도려낸 무결점의 날붙이. 끝내 손에서 놓지 않고 보관한다.”': '“第 7 号最终版：剜去前五件试制品所有缺陷的无瑕利刃。始终不离手地保存。”',
        '“…허나 어째서 우물 바닥에 버려졌던 첫 번째 파편이, 모루 위의 완성작보다 더 날카롭게 울리는가.”': '“……可为何被丢弃在井底的第一块碎片，鸣响得比铁砧上的完成之作更加锋利？”',
        '(벼림꾼 오르가의 모루터 폐기 장부 제7항)': '（锻造师奥尔加的铁砧废弃账簿第 7 项）',
        '잔향체, 아스트라': '余响体，阿斯特拉',
        '영구 스킬트리 포인트 +2': '永久技能树点数 +2',
        '다섯 별의 잔향이 뭉친 아스트라를 쓰러뜨린 기록입니다.': '击败由五颗星的余响凝聚而成的阿斯特拉的记录。',
        '“다섯 은하의 군주가 소멸한 궤도 위에, 별들의 유언이 뭉쳐 하나의 잔향체가 깨어났다.”': '“在五大星系君主消亡的轨道上，群星的遗言凝聚，一个余响体苏醒了。”',
        '“하말리스의 장갑, 디프다르의 심연, 주베누비아의 균형, 주벤샤말의 심판, 에니프론의 붕괴.”': '“哈马利斯的装甲，迪夫达的深渊，祖贝努比亚的均衡，祖本沙玛利的审判，埃尼弗隆的崩毁。”',
        '“다섯 별의 무게를 모두 베어낸 칼날만이 성간(星間)의 침묵을 통과한다.”': '“唯有斩尽五颗星之重的刀刃，才能穿过星际的寂静。”',
        '지핵군주, 모르그란': '地核君主，莫格兰',
        '지하계 끝에서 지핵군주 모르그란을 쓰러뜨린 기록입니다.': '在地下界尽头击败地核君主莫格兰的记录。',
        '“지하계의 끝은 암반이 아니라 세계수의 뿌리를 아래에서 태우던 거대한 지핵(地核)의 심장이었다.”': '“地下界的尽头不是岩层，而是自下方灼烧世界树之根的巨大地核之心。”',
        '“모르그란의 용광로가 식자, 뿌리 아래를 짓누르던 영겁의 침묵에 첫 균열이 갔다.”': '“莫格兰的熔炉冷却之时，压在根下的永劫寂静第一次出现了裂痕。”',
        '무광해의 포식자, 탈라사': '无光之海的掠食者，塔拉萨',
        '무광해의 해구에서 포식자 탈라사를 쓰러뜨린 기록입니다.': '在无光之海的海沟中击败掠食者塔拉萨的记录。',
        '“빛이 닿지 않는 천 미터 해구(海溝)에서, 뿌리가 흘린 썩은 수액을 먹고 자란 고대 포식자의 기록.”': '“在光照不到的千米海沟中，以根部流出的腐烂树液为食长大的古代掠食者的记录。”',
        '“검은 조류를 가르고 돌아온 칼날에는 심해의 수압조차 꺾지 못한 서슬이 남았다.”': '“劈开黑色洋流归来的刀刃上，留着连深海水压也无法折断的锋芒。”',
        '빈 왕좌의 집행자, 카엘룸': '空王座的执行者，凯鲁姆',
        // ── 2026-11-04 표에서 넣음(w2b06-zh-CN.json) ──
        '창공의 탑 꼭대기에서 빈 왕좌의 집행자 카엘룸을 멈춰 세운 기록입니다.': '在苍穹之塔顶端阻止空王座执行者卡埃鲁姆的记录。',
        '“창공의 탑 꼭대기에 놓인 왕좌는 태초부터 주인이 없었다.”': '“苍穹之塔顶端的王座，自太初起便没有主人。”',
        '“텅 빈 왕좌의 질서를 수호하던 자동 집행자가 멈춰 서자, 수관 너머의 천공이 비로소 열렸다.”': '“守护空王座秩序的自动执行者停下时，树冠之外的天空终于打开了。”',
        '경계의 관측자, 베일라': '边界的观测者，薇拉',
        '마지막 경계에서 관측자 베일라를 넘어선 기록입니다.': '在最后的边界越过观测者薇拉的记录。',
        '(경계 너머에 남은 마지막 기록)': '（边界之外留下的最后记录）',
        '“지핵의 바닥, 무광해의 심연, 창공의 빈 왕좌, 그리고 다섯 별의 잔향까지 모든 기록이 수렴되었다.”': '“地核之底、无光海之渊、苍穹的空王座，乃至五星的残响，一切记录都已汇聚。”',
        '“관측이 종료된 순간, 세계는 우물에서 기어 나온 첫 번째 날붙이를 더 이상 누군가의 도구라 부를 수 없었다.”': '“观测结束的那一刻，世界再也无法把从井中爬出的第一把刃称作任何人的工具。”',
        '관련 장소에서 기억의 잎 발견': '在相关地点发现记忆之叶',
