        '몬스터를 쓰러뜨린 만큼 내려갑니다. 정예는 {eliteKillMul}배입니다.': '击杀多少怪物就下潜多少。精英计{eliteKillMul}倍。',
        '{value}m마다 길을 막고, 닿으면 남은 무리를 두고 바로 가디언 방으로 갑니다. 쓰러뜨려야 더 내려가고, 가디언에게 쓰러지면 잠수가 끝납니다.': '每{value}m挡路一次，到达后放下剩余敌群直接进入守护者房间。必须击倒才能继续下潜，被守护者击倒则潜水结束。',
        '초당 {st} 줄어들고, 철갑 패각충과 정예, 가디언이 부른 졸개를 쓰러뜨리면 공기 방울로 찹니다. 다 떨어지면 익사 피해를 받다가 수면으로 올라와 잠수를 시작한 사냥터로 돌아오고, 체크포인트 뒤 진행은 사라집니다.': '每秒减少{st}，击倒铁甲贝壳虫、精英及守护者召唤的小怪可用气泡补充。耗尽后受到溺水伤害并上浮，回到开始潜水的猎场，检查点之后的进度消失。',
        '켜 두면 산소가 떨어지거나 가디언에게 쓰러져 떠오른 뒤, 사냥터 하나를 깨고 다시 잠수합니다. 가디언 앞에 막혔으면 지난 가디언 자리부터 내려가 물고기를 모읍니다. 무리에게 쓰러지거나, 리프트도 가디언 처치도 물고기도 없이 {missLimit}번 떠오르면 멈춥니다. 새 루프의 첫 잠수와 자리를 비운 동안의 정산에서는 다시 잠수하지 않습니다.': '开启后，因氧气耗尽或被守护者击倒上浮后，会通关一个猎场并再次潜水。若被守护者挡住，则从上一个守护者位置下潜收集鱼。被敌群击倒，或在没有升降、没有击倒守护者、没有鱼的情况下上浮{missLimit}次则停止。新循环的首次潜水与离线结算期间不会再次潜水。',
